#!/usr/bin/env bash
# =============================================================================
# KAHADE — SECURITY REMEDIATION SCRIPT
# Generated by: Security Audit (Feb 23 2026)
# =============================================================================
# Usage:
#   chmod +x fix_all.sh
#   ./fix_all.sh [path-to-repo]
#
# Defaults to current directory if no argument given.
# Idempotent: safe to run multiple times.
# Creates git branch: security/audit-fixes-<timestamp>
# =============================================================================
set -euo pipefail

REPO_ROOT="${1:-$(pwd)}"
TIMESTAMP="$(date +%Y%m%d_%H%M%S)"
LOG_DIR="$REPO_ROOT/audit-logs/$TIMESTAMP"
GIT_BRANCH="security/audit-fixes-$TIMESTAMP"
MANUAL_TODOS="$REPO_ROOT/manual_todos.txt"

# ── Colors ─────────────────────────────────────────────────────────────────────
RED='\033[0;31m' GREEN='\033[0;32m' YELLOW='\033[1;33m' CYAN='\033[0;36m' NC='\033[0m'
ok()   { echo -e "${GREEN}[✔]${NC} $*"; }
warn() { echo -e "${YELLOW}[!]${NC} $*"; }
err()  { echo -e "${RED}[✘]${NC} $*" >&2; }
hdr()  { echo -e "\n${CYAN}══════════════════════════════════════════${NC}"; echo -e "${CYAN}  $*${NC}"; echo -e "${CYAN}══════════════════════════════════════════${NC}"; }

# ── Preflight ──────────────────────────────────────────────────────────────────
hdr "Kahade Security Remediation"
echo "Repo: $REPO_ROOT"
echo "Logs: $LOG_DIR"

[ ! -d "$REPO_ROOT/backend" ] && { err "backend/ not found in $REPO_ROOT"; exit 1; }
[ ! -d "$REPO_ROOT/frontend" ] && { err "frontend/ not found in $REPO_ROOT"; exit 1; }
command -v git  >/dev/null || { err "git not found"; exit 1; }
command -v node >/dev/null || { err "node not found"; exit 1; }

mkdir -p "$LOG_DIR"

# ── Git branch ────────────────────────────────────────────────────────────────
hdr "1. Git Setup"
cd "$REPO_ROOT"
if git rev-parse --is-inside-work-tree &>/dev/null; then
  git checkout -b "$GIT_BRANCH" 2>/dev/null || git checkout "$GIT_BRANCH"
  ok "Branch: $GIT_BRANCH"
else
  warn "Not a git repo — skipping branch creation"
fi

# ══════════════════════════════════════════════════════════════════════════════
# FIX 1: Harden env.validation.ts — make all critical secrets required in prod
# ══════════════════════════════════════════════════════════════════════════════
hdr "FIX 1: Harden env validation (require secrets in production)"
ENV_VAL="$REPO_ROOT/backend/src/config/env.validation.ts"
if grep -q "Joi.string().optional().default('dev-jwt-secret" "$ENV_VAL" 2>/dev/null; then
  cat > "$ENV_VAL" << 'ENVEOF'
import * as Joi from 'joi';

/**
 * Helper: a secret that must be at least `minLength` chars in production,
 * but gets a dev placeholder in non-production environments.
 */
const productionSecret = (minLength = 32) =>
  Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().min(minLength).required(),
    otherwise: Joi.string().optional().default(`dev-placeholder-change-me-${minLength}chars`),
  });

export const envValidationSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test')
    .default('development'),
  PORT: Joi.number().default(3001),
  FRONTEND_URL: Joi.string().optional().default('http://localhost:5000'),
  API_PREFIX: Joi.string().default('api'),
  ENABLE_SWAGGER: Joi.string().valid('true', 'false').default('false'),

  DATABASE_URL: Joi.string().required(),
  POSTGRES_USER: Joi.string().optional(),
  POSTGRES_PASSWORD: Joi.string().optional(),
  POSTGRES_DB: Joi.string().optional(),

  REDIS_HOST: Joi.string().optional().default('localhost'),
  REDIS_PORT: Joi.number().default(6379),
  REDIS_PASSWORD: Joi.string().optional().allow(''),
  REDIS_DB: Joi.number().default(0),
  REDIS_URL: Joi.string().optional(),
  REDIS_ENABLED: Joi.string().valid('true', 'false').default('false'),
  REDIS_TLS_ENABLED: Joi.string().valid('true', 'false').default('false'),

  // SECURITY: Required in production, min 32 chars
  JWT_SECRET: productionSecret(32),
  JWT_REFRESH_SECRET: productionSecret(32),
  JWT_ACCESS_TOKEN_EXPIRY: Joi.string().default('15m'),
  JWT_REFRESH_TOKEN_EXPIRY: Joi.string().default('7d'),

  ENCRYPTION_KEY: productionSecret(32),
  ENCRYPTION_IV: Joi.string().optional().default('dev-iv-16-chars!!'),

  SESSION_SECRET: productionSecret(32),
  COOKIE_SECRET: productionSecret(32),
  CSRF_SECRET: productionSecret(32),
  BCRYPT_ROUNDS: Joi.number().min(10).max(14).default(12),

  // Payment gateway tokens — required in production
  XENDIT_CALLBACK_TOKEN: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().min(16).required(),
    otherwise: Joi.string().optional().allow(''),
  }),
  MIDTRANS_SERVER_KEY: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().min(8).required(),
    otherwise: Joi.string().optional().allow(''),
  }),
  MIDTRANS_CLIENT_KEY: Joi.string().optional().allow(''),
  MIDTRANS_IS_PRODUCTION: Joi.boolean().default(false),

  SMTP_HOST: Joi.string().optional().allow(''),
  SMTP_PORT: Joi.number().default(587),
  SMTP_SECURE: Joi.string().valid('true', 'false').default('false'),
  SMTP_USER: Joi.string().optional().allow(''),
  SMTP_PASSWORD: Joi.string().optional().allow(''),
  SMTP_FROM_NAME: Joi.string().default('Kahade'),
  SMTP_FROM_EMAIL: Joi.string().default('noreply@kahade.id'),

  THROTTLE_TTL: Joi.number().default(60),
  THROTTLE_LIMIT: Joi.number().default(100),
  THROTTLE_LOGIN_LIMIT: Joi.number().default(5),
  THROTTLE_OTP_LIMIT: Joi.number().default(3),

  CORS_ORIGIN: Joi.string().optional(),
  CORS_CREDENTIALS: Joi.boolean().default(true),
  HSTS_MAX_AGE: Joi.number().default(31536000),

  MAX_FILE_SIZE: Joi.number().default(10485760),
  UPLOAD_PATH: Joi.string().default('./uploads'),
  ALLOWED_FILE_TYPES: Joi.string().default('image/jpeg,image/png,image/webp,application/pdf'),

  SENTRY_DSN: Joi.string().uri().optional().allow(''),
  LOG_LEVEL: Joi.string().valid('error', 'warn', 'info', 'debug').default('info'),
  ENABLE_METRICS: Joi.string().valid('true', 'false').default('true'),
  LOG_FILE_PATH: Joi.string().default('./logs'),

  ENABLE_2FA: Joi.boolean().default(true),
  ENABLE_EMAIL_VERIFICATION: Joi.boolean().default(true),
  ENABLE_SMS_VERIFICATION: Joi.boolean().default(false),
}).options({ allowUnknown: true });
ENVEOF
  ok "env.validation.ts hardened"
else
  ok "FIX 1: Already applied (skipping)"
fi

