# ══════════════════════════════════════════════════════════════════════════════
# FIX 4: Enable magic bytes validation in FileUploadValidator
# ══════════════════════════════════════════════════════════════════════════════
hdr "FIX 4: Enable magic bytes (file signature) validation"
FUV_FILE="$REPO_ROOT/backend/src/common/validators/file-upload.validator.ts"
if grep -q 'Implement magic byte validation' "$FUV_FILE" 2>/dev/null; then
  # Use python3 for reliable multi-line replacement
  python3 - "$FUV_FILE" << 'PYEOF'
import sys
fpath = sys.argv[1]
with open(fpath) as f:
    content = f.read()

old = """    // 6. Validate magic bytes (file signature) match MIME type
    // NOTE: Implement magic byte validation - Tracked in backlog
    // This requires reading file header and comparing with known signatures
    // Example: JPEG should start with FF D8 FF

    return file;"""
new = """    // 6. Validate magic bytes — SECURITY FIX (was previously not called)
    if (file.buffer && file.buffer.length > 4) {
      const signatureValid = await FileSignatureChecker.validate(file);
      if (!signatureValid) {
        throw new BadRequestException(
          `File content does not match declared MIME type ${file.mimetype}. Possible file-type spoofing detected.`,
        );
      }
    }

    return file;"""
if old in content:
    content = content.replace(old, new, 1)
    with open(fpath, 'w') as f:
        f.write(content)
    print("Magic bytes check enabled")
else:
    print("Pattern not found — may already be applied")
PYEOF
  ok "Magic bytes validation enabled"
else
  ok "FIX 4: Already applied (skipping)"
fi

