# ══════════════════════════════════════════════════════════════════════════════
# FIX 12: Fix broken timingSafeEqual in crypto-safe.util.ts
# ══════════════════════════════════════════════════════════════════════════════
hdr "FIX 12: Fix timingSafeEqual implementation"
CRYPTO_SAFE="$REPO_ROOT/backend/src/common/utils/crypto-safe.util.ts"
if grep -q 'randomBytes(0).compare' "$CRYPTO_SAFE" 2>/dev/null; then
  python3 - "$CRYPTO_SAFE" << 'PYEOF'
import sys
fpath = sys.argv[1]
with open(fpath) as f:
    content = f.read()

# Fix import
content = content.replace(
    "import { randomBytes, randomInt } from 'crypto';",
    "import { randomBytes, randomInt, timingSafeEqual as cryptoTimingSafeEqual } from 'crypto';"
)

# Fix the function
old_fn = '''export function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) {
    return false;
  }

  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');

  try {
    return randomBytes(0).compare(bufA, bufB) === 0;
  } catch {
    // Fallback to constant-time comparison
    let result = 0;
    for (let i = 0; i < bufA.length; i++) {
      result |= bufA[i] ^ bufB[i];
    }
    return result === 0;
  }
}'''
new_fn = '''export function timingSafeEqual(a: string, b: string): boolean {
  // SECURITY FIX: Use crypto.timingSafeEqual directly (previous impl used
  // randomBytes(0).compare() which throws ERR_INVALID_ARG_TYPE and is NOT timing-safe).
  // Per NIST SP 800-107: compare same-length buffers in constant time.
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');

  // Must be same length for cryptoTimingSafeEqual
  if (bufA.length !== bufB.length) {
    // Run a dummy comparison anyway to avoid length-based timing oracle
    const dummy = Buffer.alloc(bufA.length);
    cryptoTimingSafeEqual(bufA, dummy);
    return false;
  }

  return cryptoTimingSafeEqual(bufA, bufB);
}'''
if old_fn in content:
    content = content.replace(old_fn, new_fn, 1)
    with open(fpath, 'w') as f:
        f.write(content)
    print("Done")
else:
    print("Pattern not found — already fixed?")
PYEOF
  ok "timingSafeEqual fixed"
else
  ok "FIX 12: Already applied (skipping)"
fi

