# FIX 8: Webhook unique constraint migration
# ══════════════════════════════════════════════════════════════════════════════
hdr "FIX 8: Add webhook idempotency unique constraint migration"
MIGRATION_DIR="$REPO_ROOT/backend/prisma/migrations/20260223000001_webhook_unique_event_id"
if [ ! -d "$MIGRATION_DIR" ]; then
  mkdir -p "$MIGRATION_DIR"
  cat > "$MIGRATION_DIR/migration.sql" << 'SQLEOF'
-- SECURITY FIX: Prevent webhook TOCTOU race condition
-- Unique constraint on (provider, eventId) prevents two concurrent webhooks
-- for the same event from both being processed.
-- Uses a partial index on active (non-FAILED) statuses to allow re-processing after failure.

-- Drop first in case of partial previous run
DROP INDEX IF EXISTS "webhook_event_unique_active";
DROP INDEX IF EXISTS "webhook_event_provider_eventId_key";

-- Partial unique index: only one active processing per (provider, eventId)
CREATE UNIQUE INDEX "webhook_event_unique_active"
  ON "WebhookEvent" ("provider", "eventId")
  WHERE "status" != 'FAILED';
SQLEOF
  ok "Webhook unique constraint migration created"
else
  ok "FIX 8: Migration already exists"
fi

